<p>Nominal: <?= html_escape((string)$event['nominal_amount']); ?>; pago: <?= html_escape((string)$event['paid_amount']); ?>; líquido: <?= html_escape((string)$event['net_amount']); ?>. Juros: <?= html_escape((string)$event['interest']); ?>; desconto: <?= html_escape((string)$event['discount']); ?>; abatimento: <?= html_escape((string)$event['abatement']); ?>; IOF: <?= html_escape((string)$event['iof']); ?>; tarifas: <?= html_escape((string)$event['fees']); ?>; outras despesas/créditos: <?= html_escape((string)$event['other_expenses'].' / '.(string)$event['other_credits']); ?>.</p>
